  const updateGroupName = (gi, name) => setOptionGroups(optionGroups.map((g, i) => i === gi ? { ...g, name } : g));
  const addOption = (gi) => setOptionGroups(optionGroups.map((g, i) => i === gi ? { ...g, options: [...g.options, { name: "", price_cents: 0 }] } : g));
  const removeOption = (gi, oi) => setOptionGroups(optionGroups.map((g, i) => i === gi ? { ...g, options: g.options.filter((_, j) => j !== oi) } : g));
  const updateOption = (gi, oi, field, value) => setOptionGroups(optionGroups.map((g, i) => i === gi ? { ...g, options: g.options.map((o, j) => j === oi ? { ...o, [field]: value } : o) } : g));
