        <div className="ui-field" style={{ width: 140 }}><label>Valor (R$)</label><input data-testid={`standalone-option-price-${oi}`} defaultValue={fmtPrice(o.price_cents)} onBlur={(e) => updateStandaloneOption(oi, "price_cents", parseCents(e.target.value))} placeholder="0,00" /></div>
